package main

import (
	"fmt"
	"net/smtp"
	"strings"
)

// BuildFeedbackEmail generates an HTML-formatted email body for user feedback.
// It constructs the email with proper headers (From, To, Subject, MIME) and
// an HTML body containing the user's name, feedback subject, and feedback content.
func BuildFeedbackEmail(fromAddr string, toAddr string, userName string, subject string, feedbackContent string) (emailBody string, err error) {
	// Validate input parameters
	if fromAddr == "" || toAddr == "" {
		return "", fmt.Errorf("fromAddr and toAddr cannot be empty")
	}
	if userName == "" {
		return "", fmt.Errorf("userName cannot be empty")
	}
	if subject == "" {
		return "", fmt.Errorf("subject cannot be empty")
	}
	if feedbackContent == "" {
		return "", fmt.Errorf("feedbackContent cannot be empty")
	}

	// Build email headers
	headers := make(map[string]string)
	headers["From"] = fromAddr
	headers["To"] = toAddr
	headers["Subject"] = fmt.Sprintf("User Feedback: %s", subject)
	headers["MIME-Version"] = "1.0"
	headers["Content-Type"] = "text/html; charset=\"UTF-8\""

	// Build HTML body
	htmlBody := buildHTMLBody(userName, subject, feedbackContent)

	// Combine headers and body
	var emailParts []string
	for key, value := range headers {
		emailParts = append(emailParts, fmt.Sprintf("%s: %s", key, value))
	}
	emailParts = append(emailParts, "")
	emailParts = append(emailParts, htmlBody)

	emailBody = strings.Join(emailParts, "\r\n")

	return emailBody, nil
}

// buildHTMLBody creates an HTML-formatted email body containing the user feedback information.
func buildHTMLBody(userName string, subject string, feedbackContent string) string {
	// Escape HTML special characters in user input to prevent XSS
	escapedUserName := escapeHTML(userName)
	escapedSubject := escapeHTML(subject)
	escapedFeedbackContent := escapeHTML(feedbackContent)

