            background-color: #4CAF50;
            color: white;
            padding: 20px;
            text-align: center;
            border-radius: 5px 5px 0 0;
        }
        .content {
            background-color: #f9f9f9;
            padding: 20px;
            border: 1px solid #dddddd;
            border-top: none;
            border-radius: 0 0 5px 5px;
        }
        .field {
            margin-bottom: 20px;
        }
        .field-label {
            font-weight: bold;
            color: #555555;
            margin-bottom: 5px;
        }
        .field-value {
            background-color: white;
            padding: 10px;
            border: 1px solid #e0e0e0;
            border-radius: 3px;
        }
        .feedback-content {
            white-space: pre-wrap;
            word-wrap: break-word;
        }
        .footer {
            margin-top: 20px;
            text-align: center;
            color: #888888;
            font-size: 12px;
        }
    </style>
</head>
<body>
    <div class="header">
        <h2>User Feedback Received</h2>
    </div>
    <div class="content">
        <div class="field">
            <div class="field-label">Submitted By:</div>
            <div class="field-value">` + escapedUserName + `</div>
        </div>
        <div class="field">
            <div class="field-label">Feedback Subject:</div>
            <div class="field-value">` + escapedSubject + `</div>
        </div>
        <div class="field">
            <div class="field-label">Feedback Content:</div>
            <div class="field-value feedback-content">` + escapedFeedbackContent + `</div>
        </div>
    </div>
    <div class="footer">
        <p>This is an automated email from the User Feedback System.</p>
    </div>
</body>
</html>`

	return html
}

// escapeHTML escapes special HTML characters to prevent XSS attacks.
func escapeHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, "\"", "&quot;")
	s = strings.ReplaceAll(s, "'", "&#39;")
	return s
}

// SendFeedbackEmail sends the feedback email using SMTP.
// This is a helper function that demonstrates how to use BuildFeedbackEmail
// and send the email via an SMTP server.
func SendFeedbackEmail(smtpHost string, smtpPort string, fromAddr string, password string, toAddr string, userName string, subject string, feedbackContent string) error {
	// Build the email
	emailBody, err := BuildFeedbackEmail(fromAddr, toAddr, userName, subject, feedbackContent)
	if err != nil {
		return fmt.Errorf("failed to build email: %w", err)
	}

	// Set up authentication
	auth := smtp.PlainAuth("", fromAddr, password, smtpHost)

	// Send the email
	addr := smtpHost + ":" + smtpPort
	err = smtp.SendMail(addr, auth, fromAddr, []string{toAddr}, []byte(emailBody))
	if err != nil {
		return fmt.Errorf("failed to send email: %w", err)
	}

	return nil
}

