	sanitizedUserName := html.EscapeString(userName)
	sanitizedSubject := html.EscapeString(subject)
	sanitizedFeedbackContent := html.EscapeString(feedbackContent)

	// Sanitize subject for email header (prevent header injection by removing CRLF)
	sanitizedEmailSubject := strings.ReplaceAll(sanitizedSubject, "\r", "")
	sanitizedEmailSubject = strings.ReplaceAll(sanitizedEmailSubject, "\n", "")

	// Construct email subject line
	emailSubject := fmt.Sprintf("Feedback: %s", sanitizedEmailSubject)

	// Construct email headers with sanitized values
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n",
		fromAddr,
		toAddr,
		emailSubject,
	)

	// Construct HTML body with escaped content to prevent XSS
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>User Feedback</title>
</head>
<body>
  <h2>User Feedback Received</h2>
  <p><strong>Submitted by:</strong> %s</p>
  <p><strong>Subject:</strong> %s</p>
  <div><strong>Message:</strong><br>
    <pre style="font-family: Arial, sans-serif; background-color: #f9f9f9; padding: 10px; border: 1px solid #ddd;">%s</pre>
  </div>
</body>
</html>`,
		sanitizedUserName,
		sanitizedSubject,
		sanitizedFeedbackContent,
	)

	// Combine headers and body
	emailMessage := headers + htmlBody

	return emailMessage, nil
}

