	}

	// Set up authentication
	auth := smtp.PlainAuth("", fromAddr, password, smtpHost)

	// Compose the message with recipients
	msg := []byte(emailBody)
	recipients := []string{toAddr}

	// Send the email
	addr := smtpHost + ":" + smtpPort
	err = smtp.SendMail(addr, auth, fromAddr, recipients, msg)
	if err != nil {
		return fmt.Errorf("failed to send email: %w", err)
	}

	return nil
}

