	}
	if _, err := mail.ParseAddress(toAddr); err != nil {
		return "", fmt.Errorf("invalid toAddr: %w", err)
	}

	// Sanitize user inputs to prevent HTML injection and header injection
	safeUserName := html.EscapeString(userName)
	safeSubject := html.EscapeString(subject)
	safeFeedbackContent := html.EscapeString(feedbackContent)

	// Sanitize subject for email header (prevent header injection by removing CRLF)
	safeEmailSubject := sanitizeHeaderValue(fmt.Sprintf("Feedback: %s", safeSubject))

	// Construct email headers with proper encoding for non-ASCII characters
	headers := fmt.Sprintf("From: %s\r\nTo: %s\r\nSubject: %s\r\nMIME-Version: 1.0\r\nContent-Type: text/html; charset=UTF-8\r\nContent-Transfer-Encoding: quoted-printable\r\n\r\n",
		fromAddr,
		toAddr,
		safeEmailSubject,
	)

	// Construct HTML body with escaped content
	htmlBody := fmt.Sprintf(`<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>User Feedback</title>
