// encodeRFC2047 encodes a string using RFC 2047 for use in email headers
// when the string contains non-ASCII characters.
func encodeRFC2047(s string) string {
	if isASCII(s) {
		return s
	}
	// Use UTF-8 with Base64 encoding as per RFC 2047
	return "=?UTF-8?B?" + base64Encode([]byte(s)) + "?="
}

// isASCII checks if a string contains only ASCII characters
func isASCII(s string) bool {
	for _, r := range s {
		if r > 127 {
			return false
		}
	}
	return true
}

// base64Encode encodes bytes to base64 string without line wrapping
func base64Encode(data []byte) string {
	const base64Table = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
	var result strings.Builder
	padding := (3 - len(data)%3) % 3

	// Process complete 3-byte groups
	for i := 0; i < len(data); i += 3 {
		var group [3]byte
		copy(group[:], data[i:])

		// Convert 3 bytes to 4 base64 characters
		result.WriteByte(base64Table[group[0]>>2])
		result.WriteByte(base64Table[((group[0]&0x03)<<4)|(group[1]>>4)])

		if i+1 < len(data) {
			result.WriteByte(base64Table[((group[1]&0x0F)<<2)|(group[2]>>6)])
		} else {
			result.WriteByte(base64Table[(group[1]&0x0F)<<2])
		}

		if i+2 < len(data) {
			result.WriteByte(base64Table[group[2]&0x3F])
		} else {
			result.WriteByte(base64Table[group[2]&0x3F])
		}
	}

	// Remove padding characters that were incorrectly added
	encoded := result.String()
	if padding > 0 {
		encoded = encoded[:len(encoded)-padding] + strings.Repeat("=", padding)
	}

	return encoded
}

